schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://c4-drift-detection-from-iac/output.schema.json",
  "title": "C4 versus IaC drift report",
  "type": "object",
  "required": [
    "system_name", "c4_model", "iac_state", "comparison_level", "mapping_table", "allowlist",
    "run", "findings", "unmapped", "reconciliation", "escalated_finding_ids", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "sha": {"type": "string", "pattern": "^[0-9a-f]{7,40}$"},
    "date": {"type": "string", "format": "date", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
    "datetime": {"type": "string", "format": "date-time"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "system_name": {"type": "string", "minLength": 3},
    "c4_model": {
      "type": "object",
      "required": ["format", "path", "commit"],
      "additionalProperties": false,
      "properties": {
        "format": {"type": "string", "enum": ["structurizr-dsl", "structurizr-json", "likec4", "model-yaml", "model-json"]},
        "path": {"type": "string", "minLength": 3},
        "commit": {"$ref": "#/definitions/sha"}
      }
    },
    "iac_state": {
      "type": "object",
      "required": ["tool", "source", "identity"],
      "additionalProperties": false,
      "properties": {
        "tool": {"type": "string", "enum": ["terraform", "pulumi", "cloudformation"]},
        "source": {"type": "string", "enum": ["terraform-show-json", "pulumi-stack-export", "cloudformation-describe-stack-resources"]},
        "identity": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "serial": {"type": "integer", "minimum": 0},
            "lineage": {"type": "string", "minLength": 8},
            "export_version": {"type": "integer", "minimum": 0},
            "stack_id": {"type": "string", "minLength": 8},
            "last_updated_at": {"$ref": "#/definitions/datetime"}
          }
        }
      },
      "allOf": [
        {"if": {"properties": {"tool": {"const": "terraform"}}}, "then": {"properties": {"source": {"const": "terraform-show-json"}, "identity": {"required": ["serial", "lineage"]}}}},
        {"if": {"properties": {"tool": {"const": "pulumi"}}}, "then": {"properties": {"source": {"const": "pulumi-stack-export"}, "identity": {"required": ["export_version"]}}}},
        {"if": {"properties": {"tool": {"const": "cloudformation"}}}, "then": {"properties": {"source": {"const": "cloudformation-describe-stack-resources"}, "identity": {"required": ["stack_id", "last_updated_at"]}}}}
      ]
    },
    "comparison_level": {"type": "string", "enum": ["container", "system-context"]},
    "mapping_table": {
      "type": "object",
      "required": ["path", "commit"],
      "additionalProperties": false,
      "properties": {
        "path": {"type": "string", "minLength": 3},
        "commit": {"$ref": "#/definitions/sha"}
      }
    },
    "allowlist": {
      "type": "object",
      "required": ["path", "commit", "hardcoded_skips_in_script", "suppressed"],
      "additionalProperties": false,
      "properties": {
        "path": {"type": "string", "minLength": 3},
        "commit": {"$ref": "#/definitions/sha"},
        "hardcoded_skips_in_script": {"type": "boolean", "const": false},
        "suppressed": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["entry", "count"],
            "additionalProperties": false,
            "properties": {
              "entry": {"type": "string", "minLength": 2},
              "count": {"type": "integer", "minimum": 0}
            }
          }
        }
      }
    },
    "run": {
      "type": "object",
      "required": ["trigger", "ran_at", "cadence", "post_apply_hook_wired"],
      "additionalProperties": false,
      "properties": {
        "trigger": {"type": "string", "enum": ["post-apply", "schedule"]},
        "ran_at": {"$ref": "#/definitions/datetime"},
        "cadence": {"type": "string", "enum": ["hourly", "daily", "weekly"]},
        "post_apply_hook_wired": {"type": "boolean", "const": true}
      }
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "class", "iac_address", "c4_element_id", "description", "closure", "reports_open"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^drift-\\d{4,}$"},
          "class": {"type": "string", "enum": ["added", "removed", "edge-changed"]},
          "iac_address": {"type": "string", "minLength": 3},
          "c4_element_id": {"type": "string", "minLength": 2},
          "description": {"type": "string", "minLength": 10},
          "closure": {
            "type": "object",
            "required": ["kind"],
            "additionalProperties": false,
            "properties": {
              "kind": {"type": "string", "enum": ["model-commit", "iac-change", "accepted", "open"]},
              "commit": {"$ref": "#/definitions/sha"},
              "reason": {"type": "string", "minLength": 10},
              "expires_on": {"$ref": "#/definitions/date"}
            },
            "allOf": [
              {"if": {"properties": {"kind": {"enum": ["model-commit", "iac-change"]}}}, "then": {"required": ["commit"]}},
              {"if": {"properties": {"kind": {"const": "accepted"}}}, "then": {"required": ["reason", "expires_on"]}}
            ]
          },
          "reports_open": {"type": "integer", "minimum": 1}
        }
      }
    },
    "unmapped": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["resource_type", "count"],
        "additionalProperties": false,
        "properties": {
          "resource_type": {"type": "string", "minLength": 3},
          "count": {"type": "integer", "minimum": 1}
        }
      }
    },
    "reconciliation": {
      "type": "object",
      "required": ["state_resources_total", "allowlisted", "mapped", "unmapped"],
      "additionalProperties": false,
      "properties": {
        "state_resources_total": {"type": "integer", "minimum": 0},
        "allowlisted": {"type": "integer", "minimum": 0},
        "mapped": {"type": "integer", "minimum": 0},
        "unmapped": {"type": "integer", "minimum": 0}
      }
    },
    "escalated_finding_ids": {"type": "array", "items": {"type": "string", "pattern": "^drift-\\d{4,}$"}},
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  }
}

output-contract.example:
{
  "system_name": "orders-platform (prod)",
  "c4_model": {"format": "structurizr-dsl", "path": "docs/c4/workspace.dsl", "commit": "3f9a2c1d"},
  "iac_state": {
    "tool": "terraform",
    "source": "terraform-show-json",
    "identity": {"serial": 412, "lineage": "6c1f0b2e-8a3d-4f5e-9b7c-1d2e3f4a5b6c"}
  },
  "comparison_level": "container",
  "mapping_table": {"path": "docs/c4/iac-mapping.yaml", "commit": "3f9a2c1d"},
  "allowlist": {
    "path": "docs/c4/iac-allowlist.yaml",
    "commit": "3f9a2c1d",
    "hardcoded_skips_in_script": false,
    "suppressed": [
      {"entry": "aws_cloudwatch_log_group", "count": 14},
      {"entry": "aws_iam_role", "count": 22},
      {"entry": "aws_iam_role_policy_attachment", "count": 31},
      {"entry": "random_id", "count": 3},
      {"entry": "aws_route53_record (same host)", "count": 6}
    ]
  },
  "run": {"trigger": "post-apply", "ran_at": "2026-09-08T14:02:11Z", "cadence": "weekly", "post_apply_hook_wired": true},
  "findings": [
    {"id": "drift-0041", "class": "added", "iac_address": "aws_sqs_queue.orders_dlq", "c4_element_id": "expected:orders.dlq", "description": "Dead-letter queue applied on 2026-09-04; no container in the model", "closure": {"kind": "model-commit", "commit": "8b1e4d7a"}, "reports_open": 1},
    {"id": "drift-0042", "class": "edge-changed", "iac_address": "aws_security_group_rule.api_to_ledger_5432", "c4_element_id": "orders.api -> ledger.db", "description": "Security group now allows orders-api to reach the ledger database directly; model shows access only via ledger-service", "closure": {"kind": "open"}, "reports_open": 1},
    {"id": "drift-0037", "class": "removed", "iac_address": "aws_elasticache_cluster.session_cache", "c4_element_id": "orders.session-cache", "description": "Session cache still in the model; removed from state at serial 398", "closure": {"kind": "accepted", "reason": "Cache is being replaced by the token service in Q4; model updated when the replacement lands", "expires_on": "2026-10-06"}, "reports_open": 2}
  ],
  "unmapped": [
    {"resource_type": "aws_msk_serverless_cluster", "count": 1}
  ],
  "reconciliation": {"state_resources_total": 131, "allowlisted": 76, "mapped": 54, "unmapped": 1},
  "escalated_finding_ids": ["drift-0037"],
  "evidence": [
    "https://ci.example.com/c4-drift/orders-platform/run/2026-09-08",
    "https://github.com/acme/orders-infra/blob/3f9a2c1d/docs/c4/iac-mapping.yaml",
    "https://github.com/acme/orders-infra/blob/3f9a2c1d/docs/c4/iac-allowlist.yaml",
    "https://ci.example.com/c4-drift/orders-platform/run/2026-09-01"
  ]
}

{
  "system_name": "orders-platform (prod)",
  "c4_model": {"format": "png", "path": "docs/architecture.png", "commit": "3f9a2c1d"},
  "iac_state": {
    "tool": "terraform",
    "source": "terraform-show-json",
    "identity": {}
  },
  "comparison_level": "container",
  "mapping_table": {"path": "docs/c4/iac-mapping.yaml", "commit": "3f9a2c1d"},
  "allowlist": {
    "path": "docs/c4/iac-allowlist.yaml",
    "commit": "3f9a2c1d",
    "hardcoded_skips_in_script": true,
    "suppressed": []
  },
  "run": {"trigger": "schedule", "ran_at": "2026-09-08T14:02:11Z", "cadence": "weekly", "post_apply_hook_wired": false},
  "findings": [
    {"id": "drift-0041", "class": "added", "iac_address": "aws_sqs_queue.orders_dlq", "c4_element_id": "expected:orders.dlq", "description": "Dead-letter queue with no container in the model", "closure": {"kind": "model-commit"}, "reports_open": 1},
    {"id": "drift-0037", "class": "removed", "iac_address": "aws_elasticache_cluster.session_cache", "c4_element_id": "orders.session-cache", "description": "Cache still in the model", "closure": {"kind": "accepted", "reason": "known, ignore"}, "reports_open": 3},
    {"id": "drift-0043", "class": "diagram-stale", "iac_address": "", "c4_element_id": "", "description": "The diagram is a bit out of date", "closure": {"kind": "open"}, "reports_open": 1}
  ],
  "unmapped": [],
  "reconciliation": {"state_resources_total": 131, "allowlisted": 0, "mapped": 54, "unmapped": 0},
  "escalated_finding_ids": [],
  "evidence": [
    "https://ci.example.com/c4-drift/orders-platform/run/2026-09-08"
  ]
}
